INSERT INTO `lessons` (`id`, `course_id`, `title`, `description`, `lesson_order`, `lesson_type`, `content_text`, `media_url`, `media_type`, `audio_url`, `audio_timestamps`, `voice_id`, `estimated_duration`, `points`, `is_mandatory`, `unlock_requirements`, `is_published`, `status`, `view_count`, `completion_rate`, `references`, `created_at`, `updated_at`) VALUES
(1, 3, 'IMPORTANCIA DE LAS SERPIENTES EN LOS ECOSISTEMAS.', NULL, 1, NULL, '<p>Las serpientes son hábiles cazadoras, muchas de ellas se alimentan de ratas, ratones, topos, insectos, arañas, escorpiones, caracoles, lagartos, tortugas, aves, murciélagos y hasta de otras serpientes.</p><table><tbody><tr><th rowspan=\"1\" colspan=\"1\"><p><img src=\"http://127.0.0.1:8000/storage/htDVEh5WhL5spnrO59rBljJNE0eO293bAhnfAgfM.png\" alt=\"Sin colmillos delanteros visibles, todos los dientes son de tama&ntilde;o similar\" data-id=\"htDVEh5WhL5spnrO59rBljJNE0eO293bAhnfAgfM.png\"></p></th><th rowspan=\"1\" colspan=\"1\"><p><img src=\"http://127.0.0.1:8000/storage/RA7Yy0kAGr744esRp0LsNjHDCrSMHaA5KFXBXewR.png\" alt=\"ladoizquierdo\" data-id=\"RA7Yy0kAGr744esRp0LsNjHDCrSMHaA5KFXBXewR.png\"></p></th></tr></tbody></table>', NULL, NULL, '/storage/audio/14f00582-8d68-4981-a754-364cf4b64edb.mp3', '{\"characters\": [\"L\", \"a\", \"s\", \" \", \"s\", \"e\", \"r\", \"p\", \"i\", \"e\", \"n\", \"t\", \"e\", \"s\", \" \", \"s\", \"o\", \"n\", \" \", \"h\", \"á\", \"b\", \"i\", \"l\", \"e\", \"s\", \" \", \"c\", \"a\", \"z\", \"a\", \"d\", \"o\", \"r\", \"a\", \"s\", \",\", \" \", \"m\", \"u\", \"c\", \"h\", \"a\", \"s\", \" \", \"d\", \"e\", \" \", \"e\", \"l\", \"l\", \"a\", \"s\", \" \", \"s\", \"e\", \" \", \"a\", \"l\", \"i\", \"m\", \"e\", \"n\", \"t\", \"a\", \"n\", \" \", \"d\", \"e\", \" \", \"r\", \"a\", \"t\", \"a\", \"s\", \",\", \" \", \"r\", \"a\", \"t\", \"o\", \"n\", \"e\", \"s\", \",\", \" \", \"t\", \"o\", \"p\", \"o\", \"s\", \",\", \" \", \"i\", \"n\", \"s\", \"e\", \"c\", \"t\", \"o\", \"s\", \",\", \" \", \"a\", \"r\", \"a\", \"ñ\", \"a\", \"s\", \",\", \" \", \"e\", \"s\", \"c\", \"o\", \"r\", \"p\", \"i\", \"o\", \"n\", \"e\", \"s\", \",\", \" \", \"c\", \"a\", \"r\", \"a\", \"c\", \"o\", \"l\", \"e\", \"s\", \",\", \" \", \"l\", \"a\", \"g\", \"a\", \"r\", \"t\", \"o\", \"s\", \",\", \" \", \"t\", \"o\", \"r\", \"t\", \"u\", \"g\", \"a\", \"s\", \",\", \" \", \"a\", \"