INSERT INTO `lesson_activities` (`id`, `lesson_id`, `title`, `activity_order`, `activity_type`, `instructions`, `content_data`, `correct_answers`, `hints`, `max_points`, `passing_score`, `time_limit`, `attempts_allowed`, `success_message`, `failure_message`, `explanation`, `is_mandatory`, `created_at`, `updated_at`) VALUES
