(3, 1, '¿Qué porcentaje de las especies de serpientes en Colombia son realmente venenosas?', 1, 'quiz_multiple', NULL, '{\"options\": [{\"text\": \"50%\", \"feedback\": null, \"is_correct\": false}, {\"text\": \" 8%\", \"feedback\": null, \"is_correct\": false}, {\"text\": \" 18%\", \"feedback\": \"Correcto! Aunque existe un miedo generalizado, solo el 18% de las aproximadamente 270 especies del país poseen veneno.\", \"is_correct\": true}, {\"text\": \"95%\", \"feedback\": null, \"is_correct\": false}]}', NULL, NULL, 10, 7, NULL, 3, NULL, NULL, 'Correcto! Aunque existe un miedo generalizado, solo el 18% de las aproximadamente 270 especies del país poseen veneno.', 1, '2025-12-20 06:24:34', '2025-12-20 06:24:34'),
(4, 1, '¿Las serpientes pueden succionar leche de los senos de mujeres lactantes?', 2, 'quiz_true_false', NULL, '{\"is_true\": \"false\", \"true_false_feedback\": \"Este es un mito popular. Las serpientes son carnívoras estrictas y sus bocas no están diseñadas para succionar líquidos de esa manera.\"}', NULL, NULL, 10, 7, NULL, 3, NULL, NULL, NULL, 1, '2025-12-20 06:24:34', '2025-12-20 06:58:30'),
(5, 1, 'Empareje el nombre común con su nombre científico', 3, 'matching', NULL, '{\"pairs\": [{\"term\": \" Mapaná \", \"match\": \"Bothrops atrox\", \"feedback\": null}, {\"term\": \" Cascabel \", \"match\": \"Crotalus durissus\", \"feedback\": null}, {\"term\": \"Rabo de Ají \", \"match\": \"Micrurus mipartitus\", \"feedback\": null}]}', NULL, NULL, 10, 7, NULL, 3, NULL, NULL, NULL, 1, '2025-12-20 06:24:34', '2025-12-20 06:58:30');
